import { I18nManager } from "./i18n";
import { uiText } from "./ui-text";
/**
 * 폰 승급(프로모션) 선택 모달
 * 상대 진영 끝에서 1턴 생존한 폰을 4종 기물(퀸, 룩, 비숍, 나이트) 중 하나로 선택하는 UI
 */

import type { PieceType } from "./config";
import type { PieceSide } from "./layout";

export interface PromotionPieceOption {
  type: PieceType;
  name: string;
  symbol: string;
  description: string;
}

export const PROMOTION_PIECE_OPTIONS: readonly PromotionPieceOption[] = [
  {
    type: "Queen",
    get name() { return I18nManager.t("lobby.piece_queen"); },
    symbol: "♕",
    get description() { return uiText("Queen"); },
  },
  {
    type: "Rook",
    get name() { return I18nManager.t("lobby.piece_rook"); },
    symbol: "♖",
    get description() { return uiText("Rook"); },
  },
  {
    type: "Bishop",
    get name() { return I18nManager.t("lobby.piece_bishop"); },
    symbol: "♗",
    get description() { return uiText("Bishop"); },
  },
  {
    type: "Knight",
    get name() { return I18nManager.t("lobby.piece_knight"); },
    symbol: "♘",
    get description() { return uiText("Knight"); },
  },
];

/**
 * 폰 승급 모달을 띄우고 선택 결과를 콜백으로 전달한다.
 */
export function openPromotionModal(
  _pieceId: string,
  side: PieceSide,
  onSelect: (chosenType: PieceType) => void,
  parentContainer?: HTMLElement,
): void {
  const container = parentContainer ?? document.body;
  const existing = document.querySelector(".promotion-modal-overlay");
  if (existing) {
    existing.remove();
  }

  const overlay = document.createElement("div");
  overlay.className = "promotion-modal-overlay";

  const card = document.createElement("div");
  card.className = "promotion-modal-card";

  const sideLabel = I18nManager.t(side === "white" ? "ingame.turn_white" : "ingame.turn_black");

  card.innerHTML = `
    <div class="promotion-modal-header">
      <h2 class="promotion-title">${uiText("promotionTitle")}</h2>
      <p class="promotion-subtitle">
        ${sideLabel} · ${uiText("promotionHint")}
      </p>
    </div>
    <div class="promotion-piece-grid">
      ${PROMOTION_PIECE_OPTIONS.map(
        (opt) => `
        <button class="promotion-piece-card" data-piece-type="${opt.type}">
          <span class="promotion-piece-symbol">${opt.symbol}</span>
          <div class="promotion-piece-info">
            <span class="promotion-piece-name">${opt.name}</span>
            <span class="promotion-piece-desc">${opt.description}</span>
          </div>
        </button>
      `,
      ).join("")}
    </div>
  `;

  overlay.appendChild(card);
  container.appendChild(overlay);

  const buttons = card.querySelectorAll<HTMLButtonElement>(
    ".promotion-piece-card",
  );
  for (const btn of buttons) {
    btn.addEventListener("click", () => {
      const chosenType = btn.dataset.pieceType as PieceType;
      overlay.classList.add("promotion-closing");
      setTimeout(() => {
        overlay.remove();
        onSelect(chosenType);
      }, 120);
    });
  }
}

import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import path from 'node:path';
import { restrictedContext } from './browser-policy.mjs';
const require = createRequire(import.meta.url);

// Executes the supplied real module in a local component scene, not a full match.
export async function withScene(web, options, inspect) {
  const gameRequire=createRequire(path.join(web,'package.json'));
  const {createServer}=await import(pathToFileURL(gameRequire.resolve('vite')).href);
  const {chromium}=require('playwright');
  const server=await createServer({root:web,configFile:false,appType:'custom',
    optimizeDeps:{noDiscovery:true,entries:[]},cacheDir:path.join(web,'../work/vite-cache'),logLevel:'error',
    server:{host:'127.0.0.1',port:0,hmr:false,fs:{allow:[web,path.dirname(gameRequire.resolve('vite'))]}},
    define:{__POKI_BUILD__:'false',__CRAZYGAMES_BUILD__:'false',__PORTABLE_BUILD__:'false'}});
  server.middlewares.use('/scene',(req,res)=>{
    res.setHeader('Content-Type','text/html');
    res.end(`<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/src/style.css"><div id="app"><button id="open">Open promotion</button></div>
      <script type="module">
      import {openPromotionModal,PROMOTION_PIECE_OPTIONS} from '/src/promotion-modal.ts';
      import {I18nManager} from '/src/i18n.ts';
      import {setMotionReduced} from '/src/ui-motion.ts';
      window.__case={calls:[],options:PROMOTION_PIECE_OPTIONS,language:I18nManager,motion:setMotionReduced,
        open(owner='current',side='white'){openPromotionModal('white-pawn-a7',side,type=>__case.calls.push({owner,type}),document.querySelector('#app'));}};
      document.querySelector('#open').onclick=()=>__case.open();window.ready=true;
      </script>`);
  });
  let browser;
  try {
    await server.listen();
    const origin=`http://127.0.0.1:${server.httpServer.address().port}`;
    browser=await chromium.launch({headless:true,...(process.env.BROWSER_PATH?{executablePath:process.env.BROWSER_PATH}:{})});
    const {context,policy}=await restrictedContext(browser,origin,{viewport:{width:360,height:800},...options});
    const page=await context.newPage();page.setDefaultTimeout(5000);
    const errors=[];page.on('pageerror',()=>errors.push('pageerror'));
    await page.goto(origin+'/scene');await page.waitForFunction(()=>window.ready);
    return await inspect({page,context,origin,policy,errors,browserVersion:browser.version()});
  } finally {try{await browser?.close();}finally{await server.close();}}
}

